package com.rental.asset;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.rental.common.error.BusinessException;
import com.rental.common.error.ErrorCode;
import com.rental.common.event.EventEnvelope;
import com.rental.common.security.HeaderUser;
import io.minio.*;
import io.minio.http.Method;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.multipart.MultipartFile;

@RestController
class AssetController {
 private final ApplianceRepository appliances; private final ReportRepository reports; private final RequestRepository requests; private final RecordRepository records; private final ScheduleRepository schedules; private final OutboxRepository outbox; private final PropertyClient property; private final ContractClient contracts; private final UserClient users; private final MinioClient minio; private final KafkaTemplate<String,String> kafka; private final ObjectMapper json;
 @Value("${asset.minio.bucket}") String bucket;
 AssetController(ApplianceRepository a,ReportRepository r,RequestRepository m,RecordRepository rec,ScheduleRepository s,OutboxRepository o,PropertyClient p,ContractClient c,UserClient u,MinioClient minio,KafkaTemplate<String,String> kafka,ObjectMapper json){this.appliances=a;this.reports=r;this.requests=m;this.records=rec;this.schedules=s;this.outbox=o;this.property=p;this.contracts=c;this.users=u;this.minio=minio;this.kafka=kafka;this.json=json;}
 private HeaderUser user(){return (HeaderUser)SecurityContextHolder.getContext().getAuthentication().getPrincipal();} private long uid(){return Long.parseLong(user().getUserId());}
 private void assigned(long staff,long building){try{if(!users.staffBuildings(staff).buildingIds().contains(building))throw new BusinessException("STAFF_NOT_IN_BUILDING","Staff chưa được phân công tại tòa nhà này",HttpStatus.UNPROCESSABLE_ENTITY);}catch(BusinessException e){throw e;}catch(Exception e){throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE,"Không thể kiểm tra phân công nhân viên");}}
 private void scope(long building){if(user().getRoles().contains("ADMIN"))return;try{if(!users.staffBuildings(uid()).buildingIds().contains(building))throw new AccessDeniedException("Bạn không có quyền thao tác trên tòa nhà này");}catch(AccessDeniedException e){throw e;}catch(Exception e){throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE,"Không thể kiểm tra phân công nhân viên");}}
 private void event(String type,Object payload,String aggregate){try{var e=EventEnvelope.of(type,payload,org.slf4j.MDC.get("correlationId"));OutboxEvent row=new OutboxEvent();row.setId(e.getEventId());row.setAggregateType("asset");row.setAggregateId(aggregate);row.setEventType(type);row.setPayload(json.valueToTree(e));outbox.save(row);}catch(Exception ex){throw new IllegalStateException("Không thể ghi outbox",ex);}}
 private <T>T required(Optional<T> value){return value.orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"Không tìm thấy dữ liệu"));}

 record ApplianceCreate(@NotNull Long roomId,@NotBlank String name,@Pattern(regexp="GOOD|NEEDS_REPAIR|BROKEN") String status){} record ApplianceUpdate(@NotBlank String name,@Pattern(regexp="GOOD|NEEDS_REPAIR|BROKEN") String status){}
 record Warranty(@NotBlank String provider,@NotNull LocalDate startDate,@NotNull LocalDate endDate){} record Upload(@NotBlank String fileName,@NotBlank String contentType){}
 record UploadUrl(String uploadUrl,String imageUrl,int expiresInSeconds){} record ReportCreate(@NotNull Long roomId,@NotBlank String title,@NotBlank String description,@Size(max=5) List<@NotBlank String> imageUrls){}
 record Approve(Long applianceId,@NotNull Long staffId,@NotNull @Pattern(regexp="LOW|MEDIUM|HIGH|URGENT") String priority,@NotNull OffsetDateTime scheduledAt){} record Reject(@NotBlank String reason){}
 record Assign(@NotNull Long staffId,@NotNull @Pattern(regexp="LOW|MEDIUM|HIGH|URGENT") String priority,@NotNull OffsetDateTime scheduledAt){} record Complete(@NotBlank String actionTaken,@DecimalMin("0.0") BigDecimal cost,@Pattern(regexp="GOOD|NEEDS_REPAIR|BROKEN") String applianceStatus){}
 record ScheduleCreate(@NotNull Long buildingId,@NotNull Long staffId,@NotBlank String title,String description,@Min(1) Integer intervalMonths,@NotNull LocalDate firstDate){} record ScheduleUpdate(@NotNull Long staffId,@NotBlank String title,String description,@Min(1) Integer intervalMonths,@NotNull LocalDate nextDate){}
 record PageResult<T>(List<T> content,int page,int size,long totalElements,int totalPages){static <T> PageResult<T> from(Page<T> result){return new PageResult<>(result.getContent(),result.getNumber(),result.getSize(),result.getTotalElements(),result.getTotalPages());}}
 private PageRequest page(int page,int size){if(page<0||size<1||size>100)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"page >= 0 và size trong khoảng 1..100");return PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"id"));}

 @PostMapping("/api/v1/appliances") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @Transactional
 @ResponseStatus(HttpStatus.CREATED) Appliance createAppliance(@Valid @RequestBody ApplianceCreate in){var room=property.getRoom(in.roomId());scope(room.buildingId());Appliance a=new Appliance();a.setRoomId(in.roomId());a.setBuildingId(room.buildingId());a.setName(in.name());a.setStatus(in.status()==null?"GOOD":in.status());return appliances.save(a);}
 @GetMapping("/api/v1/appliances") @PreAuthorize("hasAnyRole('QUAN_LY','KY_THUAT','SALE','ADMIN')") PageResult<Appliance> listAppliances(@RequestParam(required=false) Long roomId,@RequestParam(required=false) Long buildingId,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var pageable=page(page,size);if(roomId!=null){var room=property.getRoom(roomId);scope(room.buildingId());return PageResult.from(appliances.findByRoomId(roomId,pageable));}if(buildingId==null)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Cần roomId hoặc buildingId");scope(buildingId);return PageResult.from(status==null?appliances.findByBuildingId(buildingId,pageable):appliances.findByBuildingIdAndStatus(buildingId,status,pageable));}
 @GetMapping("/api/v1/appliances/{id}") @PreAuthorize("hasAnyRole('QUAN_LY','KY_THUAT','SALE','ADMIN')") Appliance appliance(@PathVariable Long id){var a=required(appliances.findById(id));scope(a.getBuildingId());return a;}
 @PutMapping("/api/v1/appliances/{id}") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") Appliance updateAppliance(@PathVariable Long id,@Valid @RequestBody ApplianceUpdate in){var a=required(appliances.findById(id));scope(a.getBuildingId());a.setName(in.name());if(in.status()!=null)a.setStatus(in.status());return appliances.save(a);}
 @PutMapping("/api/v1/appliances/{id}/warranty") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") Appliance warranty(@PathVariable Long id,@Valid @RequestBody Warranty w){if(w.endDate().isBefore(w.startDate()))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Ngày hết hạn phải sau ngày bắt đầu");var a=required(appliances.findById(id));scope(a.getBuildingId());a.setWarrantyProvider(w.provider());a.setWarrantyStartDate(w.startDate());a.setWarrantyEndDate(w.endDate());return appliances.save(a);}
 @DeleteMapping("/api/v1/appliances/{id}") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void deleteAppliance(@PathVariable Long id){var a=required(appliances.findById(id));scope(a.getBuildingId());appliances.delete(a);}

 @PostMapping("/api/v1/reports/image-upload-url") @PreAuthorize("hasRole('CUSTOMER')") UploadUrl uploadUrl(@Valid @RequestBody Upload in){String type=in.contentType().toLowerCase(Locale.ROOT);if(!Set.of("image/jpeg","image/png","image/webp").contains(type))throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Chỉ hỗ trợ JPG, PNG hoặc WEBP");String ext=switch(type){case "image/jpeg"->"jpg";case "image/png"->"png";default->"webp";};String object=UUID.randomUUID()+"."+ext;try{String put=minio.getPresignedObjectUrl(GetPresignedObjectUrlArgs.builder().method(Method.PUT).bucket(bucket).object(object).expiry(10,TimeUnit.MINUTES).extraHeaders(Map.of("Content-Type",type)).build());String get=minio.getPresignedObjectUrl(GetPresignedObjectUrlArgs.builder().method(Method.GET).bucket(bucket).object(object).expiry(7,TimeUnit.DAYS).build());return new UploadUrl(put,get,600);}catch(Exception e){throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE,"Không thể tạo liên kết tải ảnh");}}
 @PostMapping("/api/v1/reports") @PreAuthorize("hasRole('CUSTOMER')") @ResponseStatus(HttpStatus.CREATED) @Transactional
 MaintenanceReport createReport(@Valid @RequestBody ReportCreate in){ContractClient.TenantInfo tenancy;try{tenancy=contracts.tenant(in.roomId(),uid());}catch(Exception e){throw new BusinessException(ErrorCode.DEPENDENCY_UNAVAILABLE,"Không thể xác minh hợp đồng thuê phòng");}if(!tenancy.isTenant())throw new BusinessException("NOT_A_TENANT_OF_ROOM","Bạn không phải người thuê hiện tại của phòng này",HttpStatus.FORBIDDEN);if(in.imageUrls()!=null&&in.imageUrls().size()>5)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Tối đa 5 ảnh");var r=new MaintenanceReport();r.setCustomerId(uid());r.setRoomId(in.roomId());r.setBuildingId(tenancy.buildingId());r.setTitle(in.title());r.setDescription(in.description());if(in.imageUrls()!=null)r.setImageUrls(in.imageUrls());r=reports.save(r);event("ReportCreated",Map.of("reportId",r.getId(),"customerId",uid(),"roomId",r.getRoomId(),"buildingId",r.getBuildingId(),"title",r.getTitle()),r.getId().toString());return r;}
 @GetMapping("/api/v1/reports/mine") @PreAuthorize("hasRole('CUSTOMER')") PageResult<MaintenanceReport> myReports(@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var pageable=page(page,size);return PageResult.from(status==null?reports.findByCustomerIdOrderByCreatedAtDesc(uid(),pageable):reports.findByCustomerIdAndStatusOrderByCreatedAtDesc(uid(),status,pageable));}
 @GetMapping("/api/v1/reports") @PreAuthorize("hasAnyRole('QUAN_LY','SALE','ADMIN')") PageResult<MaintenanceReport> reports(@RequestParam Long buildingId,@RequestParam(required=false) String status,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){scope(buildingId);var pageable=page(page,size);return PageResult.from(status==null?reports.findByBuildingIdOrderByCreatedAtDesc(buildingId,pageable):reports.findByBuildingIdAndStatusOrderByCreatedAtDesc(buildingId,status,pageable));}
 @GetMapping("/api/v1/reports/{id}") @PreAuthorize("hasAnyRole('CUSTOMER','QUAN_LY','KY_THUAT','SALE','ADMIN')") MaintenanceReport report(@PathVariable Long id){var r=required(reports.findById(id));if(user().getRoles().contains("CUSTOMER")){if(r.getCustomerId()!=uid())throw new AccessDeniedException("Không có quyền xem báo cáo này");}else if(!user().getRoles().contains("ADMIN")){scope(r.getBuildingId());}return r;}
 @PutMapping("/api/v1/reports/{id}/approve") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @Transactional MaintenanceRequest approve(@PathVariable Long id,@Valid @RequestBody Approve in){var r=required(reports.findById(id));scope(r.getBuildingId());if(!r.getStatus().equals("PENDING"))throw new BusinessException("INVALID_STATUS","Báo cáo đã được xử lý",HttpStatus.UNPROCESSABLE_ENTITY);assigned(in.staffId(),r.getBuildingId());var m=new MaintenanceRequest();m.setReportId(id);m.setApplianceId(in.applianceId());m.setRoomId(r.getRoomId());m.setBuildingId(r.getBuildingId());m.setStaffId(in.staffId());m.setPriority(in.priority()==null?"MEDIUM":in.priority());m.setScheduledAt(in.scheduledAt());r.setStatus("APPROVED");reports.save(r);m=requests.save(m);event("MaintenanceRequestAssigned",Map.of("maintenanceRequestId",m.getId(),"reportId",id,"customerId",r.getCustomerId(),"staffId",m.getStaffId(),"roomId",m.getRoomId(),"buildingId",m.getBuildingId(),"priority",m.getPriority(),"scheduledAt",m.getScheduledAt()),m.getId().toString());return m;}
 @PutMapping("/api/v1/reports/{id}/reject") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @Transactional MaintenanceReport reject(@PathVariable Long id,@Valid @RequestBody Reject in){var r=required(reports.findById(id));scope(r.getBuildingId());if(!r.getStatus().equals("PENDING"))throw new BusinessException("INVALID_STATUS","Báo cáo đã được xử lý",HttpStatus.UNPROCESSABLE_ENTITY);r.setStatus("REJECTED");r.setRejectReason(in.reason());r=reports.save(r);event("ReportRejected",Map.of("reportId",id,"customerId",r.getCustomerId(),"reason",in.reason()),id.toString());return r;}

 @GetMapping("/api/v1/maintenance-requests") @PreAuthorize("hasAnyRole('QUAN_LY','KY_THUAT','SALE','ADMIN')") PageResult<MaintenanceRequest> listRequests(@RequestParam(required=false) Long buildingId,@RequestParam(required=false) Long staffId,@RequestParam(required=false) String status,@RequestParam(required=false) String priority,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var pageable=page(page,size);if(user().getRoles().contains("KY_THUAT"))return PageResult.from(requests.findRequests(buildingId,uid(),status,priority,pageable));if(!user().getRoles().contains("ADMIN")){if(buildingId==null)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Cần buildingId");scope(buildingId);}return PageResult.from(requests.findRequests(buildingId,staffId,status,priority,pageable));}
 @GetMapping("/api/v1/maintenance-requests/mine") @PreAuthorize("hasRole('CUSTOMER')") PageResult<MaintenanceRequest> myRequests(@RequestParam(required=false) String status,@RequestParam(required=false) String priority,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){var pageable=page(page,size);return PageResult.from(requests.findByCustomerReports(uid(),status,priority,pageable));}
 @GetMapping("/api/v1/maintenance-requests/{id}") @PreAuthorize("hasAnyRole('CUSTOMER','QUAN_LY','KY_THUAT','SALE','ADMIN')") MaintenanceRequest oneRequest(@PathVariable Long id){var m=required(requests.findById(id));if(user().getRoles().contains("CUSTOMER")){var r=required(reports.findById(m.getReportId()));if(r.getCustomerId()!=uid())throw new AccessDeniedException("Không có quyền xem phiếu này");}else if(user().getRoles().contains("KY_THUAT")){if(m.getStaffId()!=uid())throw new AccessDeniedException("Phiếu không được giao cho bạn");}else if(!user().getRoles().contains("ADMIN")){scope(m.getBuildingId());}return m;}
 @PutMapping("/api/v1/maintenance-requests/{id}/assign") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @Transactional MaintenanceRequest assign(@PathVariable Long id,@Valid @RequestBody Assign in){var m=required(requests.findById(id));scope(m.getBuildingId());assigned(in.staffId(),m.getBuildingId());m.setStaffId(in.staffId());m.setPriority(in.priority());m.setScheduledAt(in.scheduledAt());m.setStatus("ASSIGNED");m=requests.save(m);var r=required(reports.findById(m.getReportId()));event("MaintenanceRequestAssigned",Map.of("maintenanceRequestId",m.getId(),"reportId",m.getReportId(),"customerId",r.getCustomerId(),"staffId",m.getStaffId(),"roomId",m.getRoomId(),"buildingId",m.getBuildingId(),"priority",m.getPriority(),"scheduledAt",m.getScheduledAt()),m.getId().toString());return m;}
 @PutMapping("/api/v1/maintenance-requests/{id}/start") @PreAuthorize("hasRole('KY_THUAT')") MaintenanceRequest start(@PathVariable Long id){var m=required(requests.findById(id));if(m.getStaffId()!=uid())throw new AccessDeniedException("Phiếu không được giao cho bạn");if(!m.getStatus().equals("ASSIGNED"))throw new BusinessException("INVALID_STATUS","Phiếu không ở trạng thái được giao",HttpStatus.UNPROCESSABLE_ENTITY);m.setStatus("IN_PROGRESS");return requests.save(m);}
 @PostMapping("/api/v1/maintenance-requests/{id}/complete") @PreAuthorize("hasAnyRole('KY_THUAT','QUAN_LY','ADMIN')") @Transactional MaintenanceRequest complete(@PathVariable Long id,@Valid @RequestBody Complete in){var m=required(requests.findById(id));if(user().getRoles().contains("KY_THUAT")){if(m.getStaffId()!=uid())throw new AccessDeniedException("Phiếu không được giao cho bạn");}else if(!user().getRoles().contains("ADMIN")){scope(m.getBuildingId());}if(!m.getStatus().equals("IN_PROGRESS"))throw new BusinessException("INVALID_STATUS","Cần bắt đầu xử lý trước khi hoàn tất",HttpStatus.UNPROCESSABLE_ENTITY);var rec=new MaintenanceRecord();rec.setMaintenanceRequestId(id);rec.setActionTaken(in.actionTaken());rec.setCost(in.cost()==null?BigDecimal.ZERO:in.cost());rec.setCompletedBy(uid());records.save(rec);m.setStatus("COMPLETED");m=requests.save(m);if(m.getApplianceId()!=null){var a=required(appliances.findById(m.getApplianceId()));a.setStatus(in.applianceStatus()==null?"GOOD":in.applianceStatus());appliances.save(a);}var r=required(reports.findById(m.getReportId()));event("MaintenanceCompleted",Map.of("maintenanceRequestId",id,"reportId",m.getReportId(),"customerId",r.getCustomerId(),"staffId",uid(),"roomId",m.getRoomId(),"buildingId",m.getBuildingId(),"cost",rec.getCost()),id.toString());return m;}

 @PostMapping("/api/v1/maintenance-schedules") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @ResponseStatus(HttpStatus.CREATED) MaintenanceSchedule createSchedule(@Valid @RequestBody ScheduleCreate in){scope(in.buildingId());assigned(in.staffId(),in.buildingId());var s=new MaintenanceSchedule();s.setBuildingId(in.buildingId());s.setStaffId(in.staffId());s.setTitle(in.title());s.setDescription(in.description());s.setIntervalMonths(in.intervalMonths());s.setNextDate(in.firstDate());return schedules.save(s);}
 @GetMapping("/api/v1/maintenance-schedules") @PreAuthorize("hasAnyRole('QUAN_LY','KY_THUAT','SALE','ADMIN')") List<MaintenanceSchedule> listSchedules(@RequestParam(required=false) Long buildingId,@RequestParam(required=false) Long staffId){if(user().getRoles().contains("KY_THUAT")){if(buildingId!=null)return schedules.findByBuildingIdAndStaffIdAndActiveTrue(buildingId,uid());return schedules.findByStaffIdAndActiveTrue(uid());}if(user().getRoles().contains("ADMIN")){if(buildingId!=null&&staffId!=null)return schedules.findByBuildingIdAndStaffIdAndActiveTrue(buildingId,staffId);if(buildingId!=null)return schedules.findByBuildingIdAndActiveTrue(buildingId);if(staffId!=null)return schedules.findByStaffIdAndActiveTrue(staffId);return schedules.findByActiveTrue();}if(buildingId==null)throw new BusinessException(ErrorCode.VALIDATION_ERROR,"Cần buildingId");scope(buildingId);if(staffId!=null)return schedules.findByBuildingIdAndStaffIdAndActiveTrue(buildingId,staffId);return schedules.findByBuildingIdAndActiveTrue(buildingId);}
 @PutMapping("/api/v1/maintenance-schedules/{id}") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") MaintenanceSchedule updateSchedule(@PathVariable Long id,@Valid @RequestBody ScheduleUpdate in){var s=required(schedules.findById(id));scope(s.getBuildingId());assigned(in.staffId(),s.getBuildingId());s.setStaffId(in.staffId());s.setTitle(in.title());s.setDescription(in.description());s.setIntervalMonths(in.intervalMonths());s.setNextDate(in.nextDate());return schedules.save(s);}
 @PostMapping("/api/v1/maintenance-schedules/{id}/complete") @PreAuthorize("hasAnyRole('KY_THUAT','QUAN_LY','ADMIN')") MaintenanceSchedule completeSchedule(@PathVariable Long id){var s=required(schedules.findById(id));if(user().getRoles().contains("KY_THUAT")){if(s.getStaffId()!=uid())throw new AccessDeniedException("Lịch không được giao cho bạn");}else if(!user().getRoles().contains("ADMIN")){scope(s.getBuildingId());}s.setLastDoneDate(LocalDate.now(ZoneOffset.UTC));s.setNextDate(s.getNextDate().plusMonths(s.getIntervalMonths()));return schedules.save(s);}
 @DeleteMapping("/api/v1/maintenance-schedules/{id}") @PreAuthorize("hasAnyRole('QUAN_LY','ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) void deleteSchedule(@PathVariable Long id){var s=required(schedules.findById(id));scope(s.getBuildingId());s.setActive(false);schedules.save(s);}
}
